shell_commands.command:
cd /testbed && git apply --recount <<'PATCH'
diff --git a/src/acl.c b/src/acl.c
--- a/src/acl.c
+++ b/src/acl.c
@@ -2377,6 +2377,8 @@
         listRewind(server.clients, &li);
         while ((ln = listNext(&li)) != NULL) {
             client *c = listNodeValue(ln);
+            /* Clients without a user, such as the primary, are not subject to ACLs. */
+            if (!c->user) continue;
             user *original = c->user;
             list *channels = NULL;
             user *new_user = ACLGetUserByName(c->user->name, sdslen(c->user->name));
PATCH
if [ $? -ne 0 ]; then exit 1; fi
make -j4 > /tmp/valkey-acl-load-build.log 2>&1 && ./runtest --single unit/acl --only 'ACL LOAD on a replica updates users without disrupting replication' > /tmp/valkey-acl-load-fixed.log 2>&1
result=$?
tail -12 /tmp/valkey-acl-load-build.log
grep -E '\[ok\]|\[err\]|All tests|fail|error|crash' /tmp/valkey-acl-load-fixed.log | tail -16
exit "$result"

